PROGRAM PartRouter

(* SFC Generated from Visual Editor *)

VAR
    (* Step Active Flags *)
    X_step_idle : BOOL := TRUE; (* Step: IDLE *)
    X_step_small : BOOL := FALSE; (* Step: SMALL *)
    X_step_large : BOOL := FALSE; (* Step: LARGE *)

    (* Step Elapsed Timers *)
    T_step_idle : TON; (* Timer for IDLE *)
    T_step_small : TON; (* Timer for SMALL *)
    T_step_large : TON; (* Timer for LARGE *)

    (* Transitions That Fire In This Scan *)
    _F_t_large : BOOL;
    _F_t_small : BOOL;
    _F_t_small_done : BOOL;
    _F_t_large_done : BOOL;
    (* Transition Conditions, as They Were Evaluated In This Scan *)
    _C_t_large : BOOL;
    _C_t_small : BOOL;
    _C_t_small_done : BOOL;
    _C_t_large_done : BOOL;

END_VAR

VAR_INPUT
    Start AT %I0.0 : BOOL; (* A part is ready *)
    IsLarge AT %I0.1 : BOOL; (* The part is large *)
END_VAR

VAR_OUTPUT
    SmallBay AT %Q0.0 : BOOL; (* Gate to the small-part bay *)
    LargeBay AT %Q0.1 : BOOL; (* Gate to the large-part bay *)
END_VAR

(* === Step Timers === *)
T_step_idle(IN := X_step_idle, PT := T#24h);
T_step_small(IN := X_step_small, PT := T#24h);
T_step_large(IN := X_step_large, PT := T#24h);

(* === Action Execution === *)
(* Action: A_IDLE *)
IF X_step_idle THEN
    SmallBay := FALSE; LargeBay := FALSE;
END_IF;

(* Action: A_SMALL *)
IF X_step_small THEN
    SmallBay := TRUE; LargeBay := FALSE;
END_IF;

(* Action: A_LARGE *)
IF X_step_large THEN
    SmallBay := FALSE; LargeBay := TRUE;
END_IF;

(* === Transition Logic === *)
(* Transition: IDLE -> LARGE (Large parts first) *)
_C_t_large := (Start AND IsLarge);
_F_t_large := X_step_idle AND _C_t_large;
(* Transition: IDLE -> SMALL (Any other part) *)
_C_t_small := (Start);
_F_t_small := X_step_idle AND _C_t_small AND NOT _F_t_large;
(* Transition: SMALL -> IDLE *)
_C_t_small_done := (T_step_small.ET >= T#30ms);
_F_t_small_done := X_step_small AND _C_t_small_done;
(* Transition: LARGE -> IDLE *)
_C_t_large_done := (T_step_large.ET >= T#30ms);
_F_t_large_done := X_step_large AND _C_t_large_done;

IF _F_t_large THEN X_step_idle := FALSE; END_IF;
IF _F_t_small THEN X_step_idle := FALSE; END_IF;
IF _F_t_small_done THEN X_step_small := FALSE; END_IF;
IF _F_t_large_done THEN X_step_large := FALSE; END_IF;
IF _F_t_large THEN X_step_large := TRUE; END_IF;
IF _F_t_small THEN X_step_small := TRUE; END_IF;
IF _F_t_small_done THEN X_step_idle := TRUE; END_IF;
IF _F_t_large_done THEN X_step_idle := TRUE; END_IF;

END_PROGRAM

